/**
 * @summary Get the unified dashboard (triage queue + seasonal campaign)
 */
export const getGetUnifiedDashboardUrl = (
  params?: GetUnifiedDashboardParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/dashboard/unified?${stringifiedParams}`
    : `/api/dashboard/unified`;
};

export const getUnifiedDashboard = async (
  params?: GetUnifiedDashboardParams,
  options?: RequestInit,
): Promise<UnifiedDashboard> => {
  return customFetch<UnifiedDashboard>(getGetUnifiedDashboardUrl(params), {
    ...options,
    method: "GET",
  });
};

