/**
 * @summary List all ag platform connections (optionally filtered by customer)
 */
export const getListAgConnectionsUrl = (params?: ListAgConnectionsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/precision-ag/connections?${stringifiedParams}`
    : `/api/precision-ag/connections`;
};

