/**
 * @summary List bulk soil-report imports for a customer
 */
export const getListSoilSampleImportsUrl = (
  id: number,
  params?: ListSoilSampleImportsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/precision-ag/customers/${id}/soil-sample-imports?${stringifiedParams}`
    : `/api/precision-ag/customers/${id}/soil-sample-imports`;
};

