/**
 * @summary List configured testing labs
 */
export const getListLabProfilesUrl = (params?: ListLabProfilesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/lab-profiles?${stringifiedParams}`
    : `/api/lab-profiles`;
};

export const listLabProfiles = async (
  params?: ListLabProfilesParams,
  options?: RequestInit,
): Promise<LabProfile[]> => {
  return customFetch<LabProfile[]>(getListLabProfilesUrl(params), {
    ...options,
    method: "GET",
  });
};

