/**
 * Provide exactly one of customerId, prospectId, workOrderId, workItemId, or expenseId. Returns attachments newest-first.
 * @summary List photo/video attachments for a customer, prospect, work order, or expense
 */
export const getListMediaAttachmentsUrl = (
  params?: ListMediaAttachmentsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/media-attachments?${stringifiedParams}`
    : `/api/media-attachments`;
};

