export const getListFertilityPlansUrl = (params?: ListFertilityPlansParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/fertility-plans?${stringifiedParams}`
    : `/api/fertility-plans`;
};

export const listFertilityPlans = async (
  params?: ListFertilityPlansParams,
  options?: RequestInit,
): Promise<FertilityPlan[]> => {
  return customFetch<FertilityPlan[]>(getListFertilityPlansUrl(params), {
    ...options,
    method: "GET",
  });
};

